package android.speech.tts;
import java.util.*;
public class TextToSpeech {
 public static final int SUCCESS=0,ERROR=-1,QUEUE_FLUSH=0,LANG_AVAILABLE=0,LANG_COUNTRY_AVAILABLE=1,LANG_COUNTRY_VAR_AVAILABLE=2,LANG_NOT_SUPPORTED=-2,LANG_MISSING_DATA=-1;
 public static class Engine { public static final String KEY_PARAM_VOLUME="volume"; }
 public interface OnInitListener { void onInit(int s); }
 public static TextToSpeech last; public static boolean synchronousInit;
 public final OnInitListener init; public UtteranceProgressListener progress;
 public final List<String> ids=new ArrayList<String>(); public int result=SUCCESS,stops=0,shutdowns=0; public boolean errorBeforeReturn=false; public static int getMaxSpeechInputLength(){return 4000;}
 public TextToSpeech(android.content.Context c,OnInitListener l){last=this;init=l;if(synchronousInit)l.onInit(SUCCESS);}
 public TextToSpeech(android.content.Context c,OnInitListener l,String engine){this(c,l);}
 public int setOnUtteranceProgressListener(UtteranceProgressListener l){progress=l;return SUCCESS;}
 public int speak(String text,int q,android.os.Bundle b,String id){ids.add(id);if(errorBeforeReturn)progress.onError(id,ERROR);return result;}
 public int synthesizeToFile(String text,android.os.Bundle b,java.io.File f,String id){ids.add(id);if(errorBeforeReturn)progress.onError(id,ERROR);return result;}
 public int stop(){stops++;if(!ids.isEmpty())progress.onError(ids.get(ids.size()-1),-1);return SUCCESS;}
 public void shutdown(){shutdowns++;}
 public int setPitch(float p){return result;} public int setSpeechRate(float r){return result;}
 public int setLanguage(Locale l){return SUCCESS;} public int isLanguageAvailable(Locale l){return LANG_COUNTRY_VAR_AVAILABLE;}
 public Set<Voice> getVoices(){return new HashSet<Voice>();} public Set<Locale> getAvailableLanguages(){return new HashSet<Locale>();}
 public Locale getLanguage(){return Locale.US;} public Voice getVoice(){return new Voice();} public int setVoice(Voice v){return SUCCESS;}
}
